#!/usr/bin/env python3
# ==============================================================================
# INVENTARIS TIPE GGUF GURU  (CPU, tanpa GPU) — SKRIP MANDIRI
# ------------------------------------------------------------------------------
# Menjawab: apakah `gguf-py` (salinan references/llama.cpp-prism, yang memuat
# kelas IQ3_S) sanggup MEMBACA semua tensor di Qwen3.8-27B-GSQ-RCO-IQ3_S.gguf.
#
# MANDIRI: gguf-py dan teacher_gguf.py disematkan sebagai basis64 karena kernel
# skrip Kaggle HANYA menyalin berkas kode ke /kaggle/src — berkas pendamping
# tidak ikut (terbukti: v1 gagal "gguf_py.tar.gz tidak ditemukan").
# Berkas guru 11,8 GB tetap di dataset dan hanya di-mount; tidak ada unduhan
# ke mesin apa pun di luar Kaggle.
# ==============================================================================

import base64
import os
import subprocess
import sys
import tarfile

TMP = "/kaggle/tmp/teacher_inspect"
os.makedirs(TMP, exist_ok=True)

_GGUF_PY_TAR_GZ_B64 = ""

_TEACHER_GGUF_PY_B64 = ""

print(">> [1/4] Membuka bundel gguf-py + teacher_gguf.py...", flush=True)
with open(os.path.join(TMP, "gguf_py.tar.gz"), "wb") as fh:
    fh.write(base64.b64decode(_GGUF_PY_TAR_GZ_B64))
with open(os.path.join(TMP, "teacher_gguf.py"), "wb") as fh:
    fh.write(base64.b64decode(_TEACHER_GGUF_PY_B64))

with tarfile.open(os.path.join(TMP, "gguf_py.tar.gz")) as tf:
    tf.extractall(os.path.join(TMP, "unpacked"))

cand = None
for root, dirs, files in os.walk(os.path.join(TMP, "unpacked")):
    if "gguf" in dirs and os.path.isfile(os.path.join(root, "gguf", "__init__.py")):
        cand = root
        break
if not cand:
    print(">> [FATAL] paket gguf tidak ditemukan setelah ekstraksi", flush=True)
    sys.exit(1)
os.environ["GGUF_PY_PATH"] = cand
print(">> [OK] GGUF_PY_PATH =", cand, flush=True)

print(">> [2/4] Mencari berkas .gguf di mount dataset...", flush=True)
model = None
for root, dirs, files in os.walk("/kaggle/input"):
    for f in files:
        if f.endswith(".gguf"):
            model = os.path.join(root, f)
            break
    if model:
        break
if not model:
    print(">> [FATAL] tidak ada berkas .gguf di bawah /kaggle/input", flush=True)
    print("   isi /kaggle/input:", sorted(os.listdir("/kaggle/input")), flush=True)
    sys.exit(1)
print(">> [OK] model:", model, os.path.getsize(model), "byte", flush=True)

print(">> [3/5] Menjalankan teacher_gguf.py inspect ...", flush=True)
rc = subprocess.run(
    [sys.executable, os.path.join(TMP, "teacher_gguf.py"), "inspect", model]
).returncode

# ---------------------------------------------------------------------------
# [4/5] Verifikasi NAMA LITERAL tensor guru terhadap peta yang sudah
# dikodekan di gsq_driver.py (DEFAULT_TEACHER_SUFFIXES). Sebelumnya hanya
# cocok-cocokan *jumlah* (851 = 16x11 + 48x14 + 3) yang sesuai; langkah ini
# mencetak string nama sebenarnya dan mengecek setiap sufiks peta driver
# benar-benar ada di berkas, dikelompokkan per jenis layer (attn penuh vs
# GDN/recurrent). Murni inventaris metadata — tidak ada dekuantisasi.
# ---------------------------------------------------------------------------
print(">> [4/5] Verifikasi nama literal vs peta gsq_driver.py ...", flush=True)
sys.path.insert(0, TMP)
import teacher_gguf as tg  # noqa: E402 — modul ditulis di langkah [1/5]

rep = tg.inspect(model)
names = [t["name"] for t in rep["tensors"]]
have = set(names)

by_layer: dict[int, set[str]] = {}
globals_: list[str] = []
for _n in names:
    _li = tg.layer_of(_n)
    if _li is None:
        globals_.append(_n)
        continue
    _parts = _n.split(".")
    by_layer.setdefault(_li, set()).add(".".join(_parts[2:-1]))

# Kelompokkan layer berdasarkan signature himpunan kunci (dua jenis dugaan:
# attn penuh punya attn_q terpisah; GDN/recurrent punya attn_qkv+attn_gate).
sigs: dict[frozenset, list[int]] = {}
for _li, _keys in by_layer.items():
    sigs.setdefault(frozenset(_keys), []).append(_li)

print(">> [NAMES] %d tensor | %d layer | %d global" % (len(names), len(by_layer), len(globals_)), flush=True)
print(">> [GLOBAL]", sorted(globals_), flush=True)
for _i, (_sig, _lis) in enumerate(sorted(sigs.items(), key=lambda kv: (len(kv[1]), sorted(kv[1])))):
    _kind = "attn_penuh" if "attn_q" in _sig else ("gdn" if "attn_qkv" in _sig else "tidak_dikenal")
    _lis_s = sorted(_lis)
    print(">> [SIGNATUR %d] %d layer jenis=%s | contoh %s..%s" % (_i, len(_lis), _kind, _lis_s[0], _lis_s[-1]), flush=True)
    print(">>   kunci(%d): %s" % (len(_sig), sorted(_sig)), flush=True)

# Peta guru bawaan gsq_driver.py (DEFAULT_TEACHER_SUFFIXES) — disalin ke sini
# agar pengecekan terjadi di Kaggle tanpa membawa konverter.
DRIVER_MAP: dict[str, list[str]] = {
    "mlp.gate_up_proj": ["ffn_gate", "ffn_up"],
    "mlp.gate_proj": ["ffn_gate"],
    "mlp.up_proj": ["ffn_up"],
    "mlp.down_proj": ["ffn_down"],
    "self_attn.q_proj": ["attn_q"],
    "self_attn.k_proj": ["attn_k"],
    "self_attn.v_proj": ["attn_v"],
    "self_attn.o_proj": ["attn_output"],
    "linear_attn.in_proj_all": ["attn_qkv", "attn_gate"],
    "linear_attn.in_proj_qkv": ["attn_qkv"],
    "linear_attn.in_proj_z": ["attn_gate"],
    "linear_attn.out_proj": ["ssm_out"],
    "lm_head": ["output"],
    "model.embed_tokens": ["token_embd"],
}

miss = 0
for _sig, _lis in sorted(sigs.items(), key=lambda kv: (len(kv[1]), sorted(kv[1]))):
    _kind = "attn_penuh" if "attn_q" in _sig else ("gdn" if "attn_qkv" in _sig else "tidak_dikenal")
    _sample = min(_lis)
    _relevant = [s for s, subs in DRIVER_MAP.items() if any(sub in _sig for sub in subs)]
    print(">> [CEK] jenis=%s layer_contoh=%d sufiks_relevan=%s" % (_kind, _sample, sorted(_relevant)), flush=True)
    for _suf in sorted(_relevant):
        for _sub in DRIVER_MAP[_suf]:
            _key = "blk.%d.%s.weight" % (_sample, _sub)
            if _key not in have:
                print(">>   [HILANG] %s" % _key, flush=True)
                miss += 1
    # Sufiks driver yang sub-nya ada di jenis ini tapi sufiks tak dianggap
    # relevan -> nama seharusnya tidak muncul; jika muncul, beri peringatan.
    for _suf, _subs in DRIVER_MAP.items():
        if _suf in _relevant:
            continue
        for _sub in _subs:
            if _sub not in _sig:
                continue
            _key = "blk.%d.%s.weight" % (_sample, _sub)
            if _key in have:
                print(">>   [PERINGATAN] %s ada di jenis %s padahal driver tak memetakan jenis ini" % (_key, _kind), flush=True)

for _suf in ("lm_head", "model.embed_tokens"):
    for _sub in DRIVER_MAP[_suf]:
        _key = "%s.weight" % _sub
        if _key not in have:
            print(">> [HILANG GLOBAL] %s" % _key, flush=True)
            miss += 1

if miss == 0:
    print(">> [HASIL] MATCH — semua kunci guru pada peta gsq_driver.py ADA di berkas", flush=True)
else:
    print(">> [HASIL] %d kunci HILANG — lihat baris [HILANG] di atas" % miss, flush=True)

# ---------------------------------------------------------------------------
# Lanjutan: VERIFIKASI BENTUK (shape). gsq_driver memakai bobot guru sebagai
# target [N, K] dan menyusun ulang kalau perlu, tapi ukuran total HARUS
# cocok (mis. gate_up guru = concat [ffn_gate; ffn_up] == [2*inter, hidden]).
# Kontrak dimensi dari MEMORY.md: hidden 5120, intermediate 17408,
# vocab 248320; GDN value_dim 6144 (H_v 48 x head_v_dim 128).
#
# Catatan orientasi: inspect() melaporkan bentuk dalam urutan NumPy [N, K],
# tapi kita TIDAK mengasumsikan itu — orientasi dideteksi dari hubungan
# transpos ffn_gate <-> ffn_down, lalu dinormalisasi.
# ---------------------------------------------------------------------------
HID, INT, VOC = 5120, 17408, 248320

_info: dict[str, tuple[tuple[int, ...], str]] = {
    t["name"]: (t["shape"], t["qtype"]) for t in rep["tensors"]
}


def _sh(name: str) -> tuple[int, ...]:
    return _info[name][0]


_g0 = _sh("blk.0.ffn_gate.weight")
if _g0[1] == HID and _g0[0] == INT:
    _ORIENT = "NK"
elif _g0[0] == HID and _g0[1] == INT:
    _ORIENT = "KN"
else:
    _ORIENT = None
print(">> [SHAPE] ffn_gate(layer0) terlapor %s -> orientasi %s" % (_g0, _ORIENT), flush=True)


def _nk(name: str) -> tuple[int, ...]:
    """Bentuk guru dinormalisasi ke [N, K] sesuai orientasi terdeteksi."""
    s = _sh(name)
    return s if _ORIENT == "NK" else (s[1], s[0])


CHK: list[tuple[str, bool]] = []


def _chk(label: str, cond: bool) -> None:
    CHK.append((label, bool(cond)))
    print(">> [%s] %s" % ("PASS" if cond else "GAGAL", label), flush=True)


if _ORIENT is None:
    _chk("orientasi ffn_gate terdeteksi (dimensi {intermediate, hidden})",
         sorted(_g0) == sorted([INT, HID]))
else:
    _chk("ffn_down == transpos ffn_gate (semua layer)",
         all(_nk("blk.%d.ffn_down.weight" % li) == (_nk("blk.%d.ffn_gate.weight" % li)[1],
                                                     _nk("blk.%d.ffn_gate.weight" % li)[0])
             for li in sorted(by_layer)))
    for _sig, _lis in sorted(sigs.items(), key=lambda kv: (len(kv[1]), sorted(kv[1]))):
        _kind = "attn_penuh" if "attn_q" in _sig else ("gdn" if "attn_qkv" in _sig else "tidak_dikenal")
        _s = min(_lis)
        _g = _nk("blk.%d.ffn_gate.weight" % _s)
        _u = _nk("blk.%d.ffn_up.weight" % _s)
        _d = _nk("blk.%d.ffn_down.weight" % _s)
        print(">> [SHAPE] jenis=%s layer=%d | gate %s up %s down %s"
              % (_kind, _s, _g, _u, _d), flush=True)
        _chk("%s: ffn_gate == [intermediate, hidden]" % _kind, _g == (INT, HID))
        _chk("%s: ffn_up == ffn_gate" % _kind, _u == _g)
        _chk("%s: ffn_down == [hidden, intermediate]" % _kind, _d == (HID, INT))
        if _kind == "attn_penuh":
            _q = _nk("blk.%d.attn_q.weight" % _s)
            _k = _nk("blk.%d.attn_k.weight" % _s)
            _v = _nk("blk.%d.attn_v.weight" % _s)
            _o = _nk("blk.%d.attn_output.weight" % _s)
            print(">> [SHAPE]   q %s k %s v %s output %s" % (_q, _k, _v, _o), flush=True)
            _chk("attn_penuh: q/k/v K == hidden", _q[1] == _k[1] == _v[1] == HID)
            # attn_output bukan [hidden, n_v]! qwen35.cpp:73 membuatnya sebagai
            # {n_embd_head_k*n_head, n_embd}: inputnya adalah keluaran HEAD gabungan
            # (head_k_dim*n_head), BUKAN n_embd_v_gqa. Setengah dari baris attn_q
            # (n_embd_head_k*n_head*2) = head_k_dim*n_head.
            _chk("attn_penuh: attn_q N == 2*head_k_dim*n_head (GQA q)",
                 _q[0] == 2 * (_q[0] // 2) and _q[0] % 2 == 0)
            _chk("attn_penuh: attn_output == [hidden, head_k_dim*n_head]",
                 _o == (HID, _q[0] // 2))
            _chk("attn_penuh: attn_output N == hidden", _o[0] == HID)
            _chk("attn_penuh: gate_up guru concat == [2*intermediate, hidden]",
                 (_g[0] + _u[0], HID) == (2 * INT, HID))
        elif _kind == "gdn":
            _qkv = _nk("blk.%d.attn_qkv.weight" % _s)
            _z = _nk("blk.%d.attn_gate.weight" % _s)
            _so = _nk("blk.%d.ssm_out.weight" % _s)
            print(">> [SHAPE]   qkv %s gate %s ssm_out %s" % (_qkv, _z, _so), flush=True)
            _chk("gdn: attn_qkv K == hidden", _qkv[1] == HID)
            _chk("gdn: attn_gate == [value_dim, hidden] (6144)", _z == (6144, HID))
            _chk("gdn: ssm_out == [hidden, value_dim] (6144)", _so == (HID, 6144))
            # in_proj_all guru = concat [attn_qkv; attn_gate] sepanjang sumbu N.
            # Cek bentuk concat eksplisit + K sama dengan hidden.
            _chk("gdn: in_proj_all guru concat == [qkv+gate, hidden]",
                 _qkv[1] == _z[1] == HID and _qkv[0] > 0 and _z[0] > 0)
            # attn_qkv N = key_dim*2 + value_dim (qwen35.cpp:81), dan value_dim
            # = baris attn_gate. Maka qkv_n - value_dim harus genap (key_dim*2).
            _chk("gdn: attn_qkv N == key_dim*2 + value_dim (selisih genap)",
                 (_qkv[0] - _z[0]) > 0 and (_qkv[0] - _z[0]) % 2 == 0)

_chk("global: token_embd == [vocab, hidden]",
     _nk("token_embd.weight") == (VOC, HID) if "token_embd.weight" in _info else False)
_chk("global: output (lm_head) == [vocab, hidden]",
     _nk("output.weight") == (VOC, HID) if "output.weight" in _info else False)

_bad = [lab for lab, ok in CHK if not ok]
if _bad:
    print(">> [HASIL-SHAPE] %d/%d cek GAGAL:" % (len(_bad), len(CHK)), flush=True)
    for lab in _bad:
        print(">>   - %s" % lab, flush=True)
else:
    print(">> [HASIL-SHAPE] MATCH — %d/%d cek bentuk & dimensi lulus" % (len(CHK), len(CHK)), flush=True)

print(">> [5/5] Selesai (rc =", rc, ")", flush=True)
sys.exit(rc)
